def count_no_of_ways(n, k):
    if n == 0:
        return 0
    dp = [0] * (n + 1)
    dp[1] = k
    dp[2] = k * k
    for i in range(3, n + 1):
        dp[i] = (dp[i - 1] * (k - 1) + dp[i - 2] * (k - 1)) % 1000000007
    return dp[n]

